<?php
$tab=(string)($_GET['tab']??'overview');$tabs=['overview'=>'Visão geral','movies'=>'Filmes','rooms'=>'Salas','shows'=>'Sessões','orders'=>'Pedidos','access'=>'Acessos'];
echo '<div class="section-heading"><div><div class="eyebrow">PAINEL DE CONTROLE</div><h1>Administração</h1></div></div><div class="tabs">';foreach($tabs as $k=>$v)echo '<a class="'.($tab===$k?'active':'').'" href="'.base('index.php?page=admin&tab='.$k).'">'.e($v).'</a>';echo '</div>';
if($tab==='overview'){$stats=['Filmes'=>(int)one('SELECT COUNT(*) n FROM movies')['n'],'Usuários'=>(int)one('SELECT COUNT(*) n FROM users')['n'],'Sessões futuras'=>(int)one('SELECT COUNT(*) n FROM showtimes WHERE starts_at>NOW()')['n'],'Pedidos'=>(int)one('SELECT COUNT(*) n FROM orders')['n']];echo '<div class="stats">';foreach($stats as $k=>$v)echo '<div class="panel stat"><span>'.e($k).'</span><strong>'.$v.'</strong></div>';echo '</div><div class="panel"><h2>Primeiros passos</h2><p>Cadastre filmes com direitos de exibição, configure salas e horários e gerencie pedidos. Para streaming, informe uma URL HTTPS do vídeo (ou um caminho uploads/ servido com acesso controlado em produção) e libere o usuário na aba Acessos.</p></div>';}
if($tab==='movies'){$edit=(int)($_GET['edit']??0);$m=$edit?one('SELECT * FROM movies WHERE id=?',[$edit]):null;echo '<div class="admin-grid"><form class="panel admin-form" method="post" enctype="multipart/form-data"><h2>'.($m?'Editar filme':'Cadastrar filme').'</h2><input type="hidden" name="_csrf" value="'.csrf().'"><input type="hidden" name="action" value="admin_movie"><input type="hidden" name="id" value="'.(int)($m['id']??0).'"><input type="hidden" name="existing_poster" value="'.e($m['poster_path']??'').'">';$inputs=['title'=>['Título','text'],'genre'=>['Gênero','text'],'release_year'=>['Ano','number'],'age_rating'=>['Classificação','text'],'duration_minutes'=>['Duração em minutos','number'],'trailer_url'=>['URL do trailer','url'],'stream_path'=>['URL HTTPS do vídeo (streaming)','text']];foreach($inputs as $key=>$v)echo '<label>'.e($v[0]).'<input '.($key==='title'?'required':'').' type="'.$v[1].'" name="'.$key.'" value="'.e($m[$key]??'').'"></label>';echo '<label>Sinopse<textarea name="description" rows="4">'.e($m['description']??'').'</textarea></label><label>Capa (JPG, PNG, WEBP, GIF até 5 MB)<input type="file" name="poster" accept="image/jpeg,image/png,image/webp,image/gif"></label>';foreach(['allow_stream'=>'Disponível no streaming','featured'=>'Destaque na página inicial','active'=>'Filme ativo'] as $key=>$label)echo '<label class="checkline"><input type="checkbox" name="'.$key.'" '.(($m?$m[$key]:($key==='active'?1:0))?'checked':'').'> '.e($label).'</label>';echo '<button class="btn full">Salvar filme</button></form><div class="panel"><h2>Filmes cadastrados</h2><div class="admin-list">';foreach(all('SELECT * FROM movies ORDER BY id DESC') as $movie)echo '<div><strong>'.e($movie['title']).'</strong><a href="'.base('index.php?page=admin&tab=movies&edit='.$movie['id']).'">Editar</a></div>';echo '</div></div></div>';}
if($tab==='rooms'){echo '<div class="admin-grid"><form class="panel admin-form" method="post"><h2>Cadastrar sala</h2><input type="hidden" name="_csrf" value="'.csrf().'"><input type="hidden" name="action" value="admin_room"><label>Nome<input required name="name"></label><label>Fileiras (1 a 20)<input required name="seat_rows" type="number" min="1" max="20" value="6"></label><label>Poltronas por fileira (1 a 30)<input required name="seats_per_row" type="number" min="1" max="30" value="8"></label><button class="btn">Cadastrar</button></form><div class="panel"><h2>Salas existentes</h2>';foreach(all('SELECT * FROM rooms ORDER BY id DESC') as $r)echo '<p>'.e($r['name']).' — '.(int)$r['seat_rows'].' × '.(int)$r['seats_per_row'].' poltronas</p>';echo '</div></div>';}
if($tab==='shows'){echo '<div class="admin-grid"><form class="panel admin-form" method="post"><h2>Nova sessão</h2><input type="hidden" name="_csrf" value="'.csrf().'"><input type="hidden" name="action" value="admin_show"><label>Filme<select name="movie_id" required>';foreach(all('SELECT id,title FROM movies WHERE active=1 ORDER BY title') as $m)echo '<option value="'.(int)$m['id'].'">'.e($m['title']).'</option>';echo '</select></label><label>Sala<select name="room_id" required>';foreach(all('SELECT id,name FROM rooms WHERE active=1 ORDER BY name') as $r)echo '<option value="'.(int)$r['id'].'">'.e($r['name']).'</option>';echo '</select></label><label>Data e horário<input required type="datetime-local" name="starts_at"></label><label>Preço (R$)<input type="number" required name="price" min="0" step="0.01" value="24.90"></label><button class="btn">Criar sessão</button></form><div class="panel"><h2>Agenda</h2><div class="admin-list">';foreach(all('SELECT s.*,m.title,r.name room FROM showtimes s JOIN movies m ON m.id=s.movie_id JOIN rooms r ON r.id=s.room_id ORDER BY s.starts_at DESC LIMIT 50') as $s)echo '<div><strong>'.e($s['title']).'</strong><small>'.date('d/m/Y H:i',strtotime($s['starts_at'])).' · '.e($s['room']).' · '.money($s['price']).'</small></div>';echo '</div></div></div>';}
if($tab==='orders'){echo '<div class="panel"><h2>Reservas e ingressos</h2><div class="table-scroll"><table><thead><tr><th>#</th><th>Cliente</th><th>Filme</th><th>Valor</th><th>Status</th><th>Atualizar</th></tr></thead><tbody>';foreach(all('SELECT o.*,u.name customer,m.title FROM orders o JOIN users u ON u.id=o.user_id JOIN showtimes s ON s.id=o.showtime_id JOIN movies m ON m.id=s.movie_id ORDER BY o.id DESC LIMIT 100') as $o){echo '<tr><td>'.(int)$o['id'].'</td><td>'.e($o['customer']).'</td><td>'.e($o['title']).'</td><td>'.money($o['total']).'</td><td>'.e($o['status']).'</td><td><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="'.csrf().'"><input type="hidden" name="action" value="admin_order"><input type="hidden" name="id" value="'.(int)$o['id'].'"><select name="status">';foreach(['pending'=>'Pendente','paid'=>'Pago','cancelled'=>'Cancelado'] as $key=>$label)echo '<option '.($o['status']===$key?'selected':'').' value="'.$key.'">'.$label.'</option>';echo '</select><button class="btn small">Salvar</button></form></td></tr>';}echo '</tbody></table></div><p class="muted">Marcar como pago é uma ação manual, não comprova recebimento real de dinheiro.</p></div>';}
if($tab==='access'){echo '<div class="admin-grid"><form class="panel admin-form" method="post"><h2>Liberar streaming</h2><input type="hidden" name="_csrf" value="'.csrf().'"><input type="hidden" name="action" value="admin_access"><label>Usuário<select name="user_id" required>';foreach(all('SELECT id,name,email FROM users ORDER BY name') as $u)echo '<option value="'.(int)$u['id'].'">'.e($u['name']).' ('.e($u['email']).')</option>';echo '</select></label><label>Filme<select name="movie_id" required>';foreach(all('SELECT id,title FROM movies WHERE allow_stream=1 ORDER BY title') as $m)echo '<option value="'.(int)$m['id'].'">'.e($m['title']).'</option>';echo '</select></label><button class="btn">Liberar acesso</button></form><div class="panel"><h2>Acessos liberados</h2>';foreach(all('SELECT u.name,m.title FROM streaming_access a JOIN users u ON u.id=a.user_id JOIN movies m ON m.id=a.movie_id ORDER BY a.created_at DESC LIMIT 40') as $row)echo '<p>'.e($row['name']).' → '.e($row['title']).'</p>';echo '</div></div>';}
